import React, {useState} from "react";
import '../styles/styles.css'


const Menu = () => { 
    const [open, setState] = useState(false); 

    return (
        <nav className = "menu">
            <nav className = {`hamburger ${open ? '-Open' :'-Closed'}`} onClick = {() => setState(!open)} >
                <img src = "../../assets/hamburger-icon.svg"></img>
            </nav>
            <nav className = {open? 'Menu-Open' : 'Menu-Closed'}> 
                <ul>
                    <li><a href = "../pages/Home">Home</a></li>
                    {/* Need to Make the login only appear on home page (in top right?) */}
                    <li><a href = "../pages/Login">Login</a></li>
                    <li><a href = "../pages/Recapped">My Recapped</a></li>
                    <li><a href = "../pages/Info">About</a></li>
                </ul>

            </nav>
        </nav>
    );
}

export default Menu;
